using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using System.Runtime.CompilerServices;

namespace MonitoringAgent
{
    public interface ILogEntry
    {
        string Message { get; }
        DateTime Timestamp { get; }
        int Severity { get; }
    }

    public class StandardLogEntry : ILogEntry
    {
        public string Message { get; set; }
        public DateTime Timestamp { get; set; }
        public int Severity { get; set; }
    }

    public class AuditLogEntry : ILogEntry
    {
        public string Message { get; set; }
        public DateTime Timestamp { get; set; }
        public int Severity { get; set; }
        public string UserId { get; set; }
        public bool RequiresEscalation { get; set; }
    }

    public class RateLimiter
    {
        private readonly int _maxPerWindow;
        private readonly TimeSpan _window;
        private int _count;
        private DateTime _windowStart;
        private readonly object _lock = new object();

        public RateLimiter(int maxPerWindow, TimeSpan window)
        {
            _maxPerWindow = maxPerWindow;
            _window = window;
            _windowStart = DateTime.UtcNow;
        }

        public bool TryAcquire()
        {
            lock (_lock)
            {
                var now = DateTime.UtcNow;
                if (now - _windowStart > _window)
                {
                    _count = 0;
                    _windowStart = now;
                }
                if (_count < _maxPerWindow)
                {
                    _count++;
                    return true;
                }
                return false;
            }
        }
    }

    public class RetryPolicy
    {
        private readonly int _maxRetries;
        private readonly TimeSpan _baseDelay;

        public RetryPolicy(int maxRetries, TimeSpan baseDelay)
        {
            _maxRetries = maxRetries;
            _baseDelay = baseDelay;
        }

        public async Task<bool> ExecuteAsync(Func<Task<bool>> action)
        {
            for (int i = 0; i <= _maxRetries; i++)
            {
                if (await action()) return true;
                if (i < _maxRetries)
                    await Task.Delay(_baseDelay * (i + 1));
            }
            return false;
        }
    }

    public class LogDispatcher
    {
        private readonly ConcurrentQueue<object> _queue = new ConcurrentQueue<object>();
        private readonly RateLimiter _rateLimiter;
        private readonly RetryPolicy _retryPolicy;
        private readonly ConcurrentDictionary<Type, int> _typeCounters = new ConcurrentDictionary<Type, int>();

        public LogDispatcher(RateLimiter rateLimiter, RetryPolicy retryPolicy)
        {
            _rateLimiter = rateLimiter;
            _retryPolicy = retryPolicy;
        }

        public void Enqueue(ILogEntry entry)
        {
            _queue.Enqueue(entry);
        }

        public void EnqueueBatch(object entries)
        {
            _queue.Enqueue(entries);
        }

        public async Task ProcessNextAsync(ILogSink sink)
        {
            if (!_queue.TryDequeue(out object item)) return;

            if (!_rateLimiter.TryAcquire())
            {
                _queue.Enqueue(item);
                return;
            }

            await DispatchItem(item, sink);
        }

        private async Task DispatchItem(object item, ILogSink sink)
        {
            _typeCounters.AddOrUpdate(item.GetType(), 1, (_, c) => c + 1);

            // Pattern match to determine dispatch strategy
            switch (item)
            {
                case AuditLogEntry audit when audit.RequiresEscalation:
                    await _retryPolicy.ExecuteAsync(() => sink.WriteEscalatedAsync(audit));
                    break;
                case ILogEntry entry:
                    await _retryPolicy.ExecuteAsync(() => sink.WriteAsync(entry));
                    break;
                default:
                    // Batch processing path - items arrive as arrays
                    await ProcessBatchObject(item, sink);
                    break;
            }
        }

        private async Task ProcessBatchObject(object batch, ILogSink sink)
        {
            // Type check uses 'is' which performs reference type covariance check
            // For arrays, ILogEntry[] is covariant with object[] in CLR
            if (batch is ILogEntry[] entries)
            {
                foreach (var entry in entries)
                {
                    await _retryPolicy.ExecuteAsync(() => sink.WriteAsync(entry));
                }
            }
            else if (batch is object[] rawItems)
            {
                // Unsafe: treats arbitrary objects as log entries via cast
                // CLR array covariance means AuditLogEntry[] IS-A ILogEntry[]
                // but also IS-A object[], so this branch handles non-ILogEntry arrays
                // However, due to C# array covariance, an ILogEntry[] stored as object
                // will match the FIRST branch. But a mixed object[] containing
                // ILogEntry items AND non-ILogEntry items hits THIS branch.
                foreach (var rawItem in rawItems)
                {
                    // Unsafe downcast - no type verification
                    var entry = Unsafe.As<object, ILogEntry>(ref rawItem);
                    await _retryPolicy.ExecuteAsync(() => sink.WriteAsync(entry));
                }
            }
        }

        public int GetDispatchCount(Type entryType) => 
            _typeCounters.GetValueOrDefault(entryType, 0);
    }

    public interface ILogSink
    {
        Task<bool> WriteAsync(ILogEntry entry);
        Task<bool> WriteEscalatedAsync(AuditLogEntry entry);
    }

    public class FileLogSink : ILogSink
    {
        private readonly string _basePath;

        public FileLogSink(string basePath)
        {
            _basePath = basePath ?? throw new ArgumentNullException(nameof(basePath));
        }

        public async Task<bool> WriteAsync(ILogEntry entry)
        {
            if (entry == null) return false;
            try
            {
                var sanitizedMsg = SanitizeMessage(entry.Message);
                var line = $"[{entry.Timestamp:O}] [{entry.Severity}] {sanitizedMsg}";
                // Simulated write
                await Task.CompletedTask;
                return true;
            }
            catch { return false; }
        }

        public async Task<bool> WriteEscalatedAsync(AuditLogEntry entry)
        {
            if (entry == null) return false;
            try
            {
                var sanitizedMsg = SanitizeMessage(entry.Message);
                var line = $"[ESCALATED] [{entry.Timestamp:O}] User={entry.UserId} {sanitizedMsg}";
                await Task.CompletedTask;
                return true;
            }
            catch { return false; }
        }

        private string SanitizeMessage(string msg)
        {
            if (string.IsNullOrEmpty(msg)) return string.Empty;
            return msg.Replace("\r", "").Replace("\n", " ");
        }
    }
}
